{"code": "const orbScript = `extends Area3D
## 能量球收集物：玩家（group "player"）进入时发出 collected 信号并消失。

signal collected(orb: Area3D)

var is_collected: bool = false

func _ready() -> void:
	body_entered.connect(_on_body_entered)

func _on_body_entered(body: Node3D) -> void:
	if is_collected:
		return
	if body.is_in_group("player"):
		_collect()

func _collect() -> void:
	is_collected = true
	collected.emit(self)
	visible = false
	set_deferred("monitoring", false)
	# 禁用碰撞形状
	for child in get_children():
		if child is CollisionShape3D:
			child.set_deferred("disabled", true)
`;

const r = await tools["mcp__godot-ai__script_create"]({ path: "res://validation_games/orbit_collector/scripts/orb.gd", content: orbScript });
console.log(JSON.stringify(r.structuredContent, null, 1));
return { ok: true };", "description": "Create orb.gd collectible script"}

{"code": "const playerScript = `extends CharacterBody3D
## Orbit Collector 玩家：键盘四向移动、收集能量球、解锁并进入出口获胜。

signal orbs_changed(collected: int, total: int)
signal exit_status_changed(unlocked: bool)
signal victory

@export var move_speed: float = 7.0
@export var total_orbs: int = 3

var orbs_collected: int = 0
var exit_unlocked: bool = false
var won: bool = false

@onready var gate: MeshInstance3D = get_node("../Props/Exit/Gate")
@onready var gate_locked_mat: Material = load("res://validation_games/orbit_collector/materials/gate_locked_mat.tres")
@onready var gate_unlocked_mat: Material = load("res://validation_games/orbit_collector/materials/gate_unlocked_mat.tres")
@onready var exit_area: Area3D = get_node("../Props/Exit/ExitArea")

func _ready() -> void:
	add_to_group("player")
	# 监听所有能量球
	for orb in get_tree().get_nodes_in_group("orbs"):
		(orb as Area3D).collected.connect(_on_orb_collected)
	# 监听出口
	exit_area.body_entered.connect(_on_exit_body_entered)
	orbs_changed.emit(orbs_collected, total_orbs)

func _physics_process(_delta: float) -> void:
	if won:
		velocity = Vector3.ZERO
		return
	var input_dir := Vector2.ZERO
	if Input.is_action_pressed("move_left"):
		input_dir.x -= 1.0
	if Input.is_action_pressed("move_right"):
		input_dir.x += 1.0
	if Input.is_action_pressed("move_forward"):
		input_dir.y -= 1.0
	if Input.is_action_pressed("move_back"):
		input_dir.y += 1.0
	input_dir = input_dir.normalized()
	velocity = Vector3(input_dir.x, 0.0, input_dir.y) * move_speed
	move_and_slide()

func _on_orb_collected(orb: Area3D) -> void:
	if won:
		return
	orbs_collected += 1
	orbs_changed.emit(orbs_collected, total_orbs)
	if orbs_collected >= total_orbs:
		_unlock_exit()

func _unlock_exit() -> void:
	exit_unlocked = true
	gate.material_override = gate_unlocked_mat
	exit_status_changed.emit(true)

func _on_exit_body_entered(body: Node3D) -> void:
	if won or not exit_unlocked:
		return
	if body == self:
		won = true
		victory.emit()
`;

const r = await tools["mcp__godot-ai__script_create"]({ path: "res://validation_games/orbit_collector/scripts/player.gd", content: playerScript });
console.log(JSON.stringify(r.structuredContent, null, 1));
return { ok: true };", "description": "Create player.gd movement and collection script"}

{"code": "const hudScript = `extends CanvasLayer
