func _ready() -> void:
	_player = get_tree().get_first_node_in_group("player") as CharacterBody3D
	if _player == null:
		return
	_player.orbs_changed.connect(_on_orbs_changed)
	_player.exit_status_changed.connect(_on_exit_status_changed)
	_player.victory.connect(_on_victory)

func _on_orbs_changed(collected: int, total: int) -> void:
	counter_label.text = "能量球: %d / %d" % [collected, total]

func _on_exit_status_changed(unlocked: bool) -> void:
	if unlocked:
